\sin{\alpha}=-\left( \cos{\alpha}-3\tan{(k\pi+\alpha)} \right) \\
\frac{\sin{\alpha}}{\cos{\alpha}}=-1+3\frac{\sin{(k\pi+\alpha)}}{\cos{(k\pi+\alpha)}} \\
\end{eqnarray}
